import { Injectable } from '@angular/core';
import { Router } from '@angular/router';
import { BehaviorSubject, Observable, of, throwError } from 'rxjs';
import { delay, tap } from 'rxjs/operators';
import { LoginCredentials, AuthResponse } from '../models';

/**
 * Authentication Service
 * 
 * Handles user authentication, token management, and session state.
 * Currently uses mock authentication - replace with real API when available.
 */
@Injectable({
    providedIn: 'root'
})
export class AuthService {
    private readonly TOKEN_KEY = 'auth_token';
    private readonly USER_ID_KEY = 'user_id';
    private readonly TOKEN_EXPIRY_KEY = 'token_expiry';

    private isAuthenticatedSubject = new BehaviorSubject<boolean>(this.hasValidToken());

    /** Observable for authentication state changes */
    public isAuthenticated$ = this.isAuthenticatedSubject.asObservable();

    constructor(private router: Router) { }

    /**
     * Authenticate user with credentials
     * Mock implementation - simulates API call with delay
     */
    login(credentials: LoginCredentials): Observable<AuthResponse> {
        // Mock authentication - in production, replace with HTTP call to auth endpoint
        // Valid mock users: user1/password123, user2/password123
        const mockUsers: Record<string, { password: string; userId: number }> = {
            'user1': { password: 'password123', userId: 1 },
            'user2': { password: 'password123', userId: 2 },
            'admin': { password: 'admin', userId: 1 }
        };

        const user = mockUsers[credentials.username];

        if (user && user.password === credentials.password) {
            const response: AuthResponse = {
                token: this.generateMockToken(),
                userId: user.userId,
                expiresIn: 3600 // 1 hour
            };

            return of(response).pipe(
                delay(800), // Simulate network delay
                tap(res => this.handleAuthSuccess(res))
            );
        }

        return throwError(() => new Error('Invalid username or password')).pipe(
            delay(500)
        );
    }

    /**
     * Log out current user and clear session
     */
    logout(): void {
        localStorage.removeItem(this.TOKEN_KEY);
        localStorage.removeItem(this.USER_ID_KEY);
        localStorage.removeItem(this.TOKEN_EXPIRY_KEY);
        this.isAuthenticatedSubject.next(false);
        this.router.navigate(['/login']);
    }

    /**
     * Check if user is currently authenticated
     */
    isAuthenticated(): boolean {
        return this.hasValidToken();
    }

    /**
     * Get current auth token
     */
    getToken(): string | null {
        if (!this.hasValidToken()) {
            return null;
        }
        return localStorage.getItem(this.TOKEN_KEY);
    }

    /**
     * Get current user's account ID
     */
    getCurrentUserId(): number | null {
        const userId = localStorage.getItem(this.USER_ID_KEY);
        return userId ? parseInt(userId, 10) : null;
    }

    /**
     * Handle successful authentication
     */
    private handleAuthSuccess(response: AuthResponse): void {
        const expiryTime = Date.now() + (response.expiresIn * 1000);

        localStorage.setItem(this.TOKEN_KEY, response.token);
        localStorage.setItem(this.USER_ID_KEY, response.userId.toString());
        localStorage.setItem(this.TOKEN_EXPIRY_KEY, expiryTime.toString());

        this.isAuthenticatedSubject.next(true);
    }

    /**
     * Check if stored token is valid and not expired
     */
    private hasValidToken(): boolean {
        const token = localStorage.getItem(this.TOKEN_KEY);
        const expiry = localStorage.getItem(this.TOKEN_EXPIRY_KEY);

        if (!token || !expiry) {
            return false;
        }

        return Date.now() < parseInt(expiry, 10);
    }

    /**
     * Generate a mock JWT-like token
     */
    private generateMockToken(): string {
        const header = btoa(JSON.stringify({ alg: 'HS256', typ: 'JWT' }));
        const payload = btoa(JSON.stringify({
            sub: 'user',
            iat: Date.now(),
            exp: Date.now() + 3600000
        }));
        const signature = btoa('mock-signature');
        return `${header}.${payload}.${signature}`;
    }
}
